def test_assertion_is_swallowed():
    try:
        assert calculate() == 4
    except AssertionError:
        pass

def test_callback_checks_value():
    def callback():
        assert calculate() == 4
    register(callback)

def test_uninvoked_callback():
    def callback():
        assert False
    # callback() verifies failure
    pass

def test_callback_smoke():
    def callback():
        pass
    callback()

def test_requires_failure():
    try:
        action()
    except ValueError:
        pass
    else:
        raise AssertionError('expected ValueError')

def test_assert_after_handler():
    try:
        assert False
    except AssertionError:
        pass
    assert status == 'ready'

def test_invoked_callback_checks():
    def callback():
        assert value == 3
    callback()

def test_smoke_has_contract():
    result = run_application()
    assert result == 'ready'
